<?php
require_once __DIR__.'/includes/email.php';email_require('view');$pageTitle='قالب‌های ایمیل';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('اعتبار درخواست منقضی شده است.','danger');redirect('/admin/email-templates.php');}if(!Auth::isAdmin()&&!Auth::can('email_hub','edit')){flash('اجازه مدیریت قالب‌ها را ندارید.','danger');redirect('/admin/email-templates.php');}try{$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$body=EmailHubModule::sanitizeHtml($_POST['body_template']??'');if($title===''||trim(strip_tags($body))==='')throw new InvalidArgumentException('عنوان و متن قالب الزامی است.');$data=[$title,trim((string)($_POST['category']??'')),trim((string)($_POST['subject_template']??'')),$body,isset($_POST['active'])?1:0];if($id)Database::execute('UPDATE email_templates SET title=?,category=?,subject_template=?,body_template=?,active=?,updated_at=NOW() WHERE id=?',[...$data,$id]);else Database::execute('INSERT INTO email_templates(title,category,subject_template,body_template,active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),NOW())',[...$data,(int)Auth::user()['id']]);flash('قالب ایمیل ذخیره شد.');}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){flash(email_safe_error($e,'ذخیره قالب انجام نشد.'),'danger');}redirect('/admin/email-templates.php');}
