<div class="email-page-head"><div><h1>قالب‌های پاسخ آماده</h1><p>پاسخ‌های استاندارد با متغیرهای هوشمند</p></div><a class="btn" href="/admin/email-compose.php">ارسال ایمیل</a></div><?php email_tabs('templates')?><?php if(Auth::isAdmin()||Auth::can('email_hub','edit')):?><section class="card email-form-card"><h2><?=$edit?'ویرایش قالب':'قالب جدید'?></h2><form method="post" data-email-compose><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><textarea name="body_template" data-email-editor-input hidden><?=e($edit['body_template']??'<p>متن پاسخ</p>')?></textarea><div class="grid grid-3"><label class="form-field"><span>عنوان قالب</span><input name="title" value="<?=e($edit['title']??'')?>" required></label><label class="form-field"><span>دسته‌بندی</span><input name="category" value="<?=e($edit['category']??'')?>"></label><label class="form-field"><span>موضوع پیش‌فرض</span><input name="subject_template" value="<?=e($edit['subject_template']??'')?>"></label><label class="checkbox-item"><input type="checkbox" name="active" <?=!isset($edit['active'])||(int)$edit['active']?'checked':''?>> فعال</label></div><div class="email-editor"><div class="email-editor-toolbar"><button type="button" data-command="bold"><b>B</b></button><button type="button" data-command="italic"><i>I</i></button><button type="button" data-command="insertUnorderedList">فهرست</button></div><div class="email-editor-surface" contenteditable="true" data-email-editor-surface><?=EmailHubModule::sanitizeHtml($edit['body_template']??'<p>متن پاسخ</p>')?></div></div><div class="email-variables"><span>{customer_name}</span><span>{ticket_number}</span><span>{current_user_name}</span><span>{current_date}</span><span>{company_name}</span></div><button class="btn btn-primary">ذخیره قالب</button></form></section><?php endif?><section class="card"><div class="table-wrap"><table><thead><tr><th>قالب</th><th>دسته</th><th>موضوع</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['title'])?></td><td><?=e($i['category']?:'عمومی')?></td><td><?=e($i['subject_template']?:'—')?></td><td><?=$i['active']?'فعال':'غیرفعال'?></td><td><?php if(Auth::isAdmin()||Auth::can('email_hub','edit')):?><a class="btn btn-small" href="?edit=<?=$i['id']?>">ویرایش</a><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
